-- Generated by scripts/history_batches/generate.py. Prepare finance without replacing source data.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
CREATE TABLE public.finance_history_entities(entity_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,account_id text NOT NULL CHECK(length(btrim(account_id))>0),championship_id text NOT NULL CHECK(length(btrim(championship_id))>0),competition_id text NOT NULL DEFAULT 'unknown',season text NOT NULL CHECK(length(btrim(season))>0),evidence_type text NOT NULL CHECK(evidence_type IN ('awards','rules','movements','team','coverage','eligibility','notifications')),source_id text NOT NULL CHECK(length(btrim(source_id))>0),UNIQUE NULLS NOT DISTINCT(account_id,championship_id,competition_id,season,evidence_type,source_id));
CREATE INDEX finance_history_scope ON public.finance_history_entities(championship_id,competition_id,season,account_id,evidence_type,source_id);
CREATE TABLE public.finance_history_states(state_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,entity_id bigint NOT NULL REFERENCES public.finance_history_entities ON DELETE CASCADE,signature text NOT NULL,payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object' AND octet_length(payload::text)<=1048576),UNIQUE(state_id,entity_id));
CREATE INDEX finance_history_state_lookup ON public.finance_history_states(entity_id,signature);
CREATE TABLE public.finance_history_times(entity_id bigint NOT NULL REFERENCES public.finance_history_entities ON DELETE CASCADE,state_id bigint NOT NULL,observed_at timestamptz NOT NULL CHECK(isfinite(observed_at)),PRIMARY KEY(entity_id,observed_at),FOREIGN KEY(state_id,entity_id) REFERENCES public.finance_history_states(state_id,entity_id) ON DELETE CASCADE);

CREATE TABLE public.finance_migration_status(id boolean PRIMARY KEY DEFAULT true CHECK(id),seeded boolean NOT NULL DEFAULT false,seed_cursor jsonb,completed_at timestamptz);
INSERT INTO public.finance_migration_status DEFAULT VALUES;
CREATE TABLE public.finance_migration_queue(entity_id bigint PRIMARY KEY REFERENCES public.finance_history_entities ON DELETE CASCADE);
CREATE TABLE public.finance_migration_verified(entity_id bigint PRIMARY KEY REFERENCES public.finance_history_entities ON DELETE CASCADE,source_rows bigint NOT NULL,endpoint_rows bigint NOT NULL,verified_at timestamptz NOT NULL);
ALTER TABLE public.finance_history_entities ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.finance_history_entities FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.finance_history_entities TO service_role;
ALTER TABLE public.finance_history_states ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.finance_history_states FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.finance_history_states TO service_role;
ALTER TABLE public.finance_history_times ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.finance_history_times FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.finance_history_times TO service_role;
ALTER TABLE public.finance_migration_status ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.finance_migration_status FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.finance_migration_status TO service_role;
ALTER TABLE public.finance_migration_queue ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.finance_migration_queue FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.finance_migration_queue TO service_role;
ALTER TABLE public.finance_migration_verified ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.finance_migration_verified FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.finance_migration_verified TO service_role;
GRANT USAGE,SELECT ON SEQUENCE public.finance_history_entities_entity_id_seq TO service_role;
GRANT USAGE,SELECT ON SEQUENCE public.finance_history_states_state_id_seq TO service_role;
DO $$ DECLARE columns text; BEGIN
 SELECT string_agg(CASE WHEN attname=ANY(ARRAY['account_id','championship_id','competition_id','season','evidence_type','source_id']) THEN 'e.' WHEN attname=ANY(ARRAY['payload']) THEN 's.' ELSE 't.' END||quote_ident(attname),',' ORDER BY attnum) INTO columns
 FROM pg_attribute WHERE attrelid='public.rival_finance_evidence'::regclass AND attnum>0 AND NOT attisdropped;
 EXECUTE 'CREATE VIEW public.finance_history_preview WITH(security_invoker=true) AS SELECT '||columns||' FROM public.finance_history_times t JOIN public.finance_history_entities e USING(entity_id) JOIN public.finance_history_states s ON s.state_id=t.state_id';
END $$;
REVOKE ALL ON public.finance_history_preview FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.finance_history_preview TO service_role;
CREATE FUNCTION public.finance_migration_changed() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE item jsonb;r public.rival_finance_evidence; v_entity bigint;
BEGIN
 IF TG_OP='TRUNCATE' THEN RAISE EXCEPTION 'History migration in progress; TRUNCATE is disabled'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(CASE TG_OP WHEN 'INSERT' THEN jsonb_build_array(to_jsonb(NEW)) WHEN 'DELETE' THEN jsonb_build_array(to_jsonb(OLD)) ELSE jsonb_build_array(to_jsonb(OLD),to_jsonb(NEW)) END) LOOP
 r:=jsonb_populate_record(NULL::public.rival_finance_evidence,item);
 -- Deletes never recreate an entity removed by a parent FK cascade.
 SELECT entity_id INTO v_entity FROM public.finance_history_entities e WHERE e.account_id IS NOT DISTINCT FROM r.account_id AND e.championship_id IS NOT DISTINCT FROM r.championship_id AND e.competition_id IS NOT DISTINCT FROM r.competition_id AND e.season IS NOT DISTINCT FROM r.season AND e.evidence_type IS NOT DISTINCT FROM r.evidence_type AND e.source_id IS NOT DISTINCT FROM r.source_id;
 IF v_entity IS NULL AND TG_OP<>'DELETE' THEN
 INSERT INTO public.finance_history_entities(account_id,championship_id,competition_id,season,evidence_type,source_id) VALUES(r.account_id,r.championship_id,r.competition_id,r.season,r.evidence_type,r.source_id) ON CONFLICT DO NOTHING;
 SELECT entity_id INTO v_entity FROM public.finance_history_entities e WHERE e.account_id IS NOT DISTINCT FROM r.account_id AND e.championship_id IS NOT DISTINCT FROM r.championship_id AND e.competition_id IS NOT DISTINCT FROM r.competition_id AND e.season IS NOT DISTINCT FROM r.season AND e.evidence_type IS NOT DISTINCT FROM r.evidence_type AND e.source_id IS NOT DISTINCT FROM r.source_id;
 END IF;
 IF v_entity IS NOT NULL THEN
 INSERT INTO public.finance_migration_queue VALUES(v_entity) ON CONFLICT(entity_id) DO UPDATE SET entity_id=excluded.entity_id;
 DELETE FROM public.finance_migration_verified WHERE entity_id=v_entity;
 END IF;
 END LOOP;
 RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION public.finance_migration_changed() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER history_migration_changed AFTER INSERT OR UPDATE OR DELETE ON public.rival_finance_evidence FOR EACH ROW EXECUTE FUNCTION public.finance_migration_changed();
CREATE TRIGGER history_migration_no_truncate BEFORE TRUNCATE ON public.rival_finance_evidence FOR EACH STATEMENT EXECUTE FUNCTION public.finance_migration_changed();
CREATE FUNCTION public.finance_migration_seed(p_limit integer DEFAULT 10000) RETURNS bigint LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE n bigint;cursor_value jsonb;predicate text:='true';
BEGIN
 IF p_limit IS NULL OR p_limit<1 OR p_limit>20000 THEN RAISE EXCEPTION 'Invalid discovery page size'; END IF;
 PERFORM 1 FROM public.finance_migration_status WHERE id FOR UPDATE;
 IF (SELECT seeded FROM public.finance_migration_status WHERE id) THEN RETURN 0; END IF;
 SELECT seed_cursor INTO cursor_value FROM public.finance_migration_status WHERE id;
 IF cursor_value IS NOT NULL THEN
 SELECT '(account_id,championship_id,competition_id,season,evidence_type,source_id,observed_at) > ('||string_agg(quote_literal(cursor_value->>k),',' ORDER BY ord)||')' INTO predicate FROM unnest(ARRAY['account_id','championship_id','competition_id','season','evidence_type','source_id','observed_at']) WITH ORDINALITY AS cols(k,ord);
 END IF;
 CREATE TEMP TABLE IF NOT EXISTS finance_seed_page ON COMMIT DROP AS SELECT account_id,championship_id,competition_id,season,evidence_type,source_id,observed_at FROM public.rival_finance_evidence WITH NO DATA;
 TRUNCATE pg_temp.finance_seed_page;
 EXECUTE 'INSERT INTO pg_temp.finance_seed_page SELECT account_id,championship_id,competition_id,season,evidence_type,source_id,observed_at FROM public.rival_finance_evidence WHERE '||predicate||' ORDER BY account_id,championship_id,competition_id,season,evidence_type,source_id,observed_at LIMIT '||p_limit;
 GET DIAGNOSTICS n=ROW_COUNT;
 INSERT INTO public.finance_history_entities(account_id,championship_id,competition_id,season,evidence_type,source_id) SELECT DISTINCT account_id,championship_id,competition_id,season,evidence_type,source_id FROM pg_temp.finance_seed_page ON CONFLICT DO NOTHING;
 INSERT INTO public.finance_migration_queue SELECT e.entity_id FROM (SELECT DISTINCT account_id,championship_id,competition_id,season,evidence_type,source_id FROM pg_temp.finance_seed_page) o JOIN public.finance_history_entities e ON e.account_id = o.account_id AND e.championship_id = o.championship_id AND e.competition_id = o.competition_id AND e.season = o.season AND e.evidence_type = o.evidence_type AND e.source_id = o.source_id ON CONFLICT DO NOTHING;
 IF n>0 THEN SELECT to_jsonb(o) INTO cursor_value FROM pg_temp.finance_seed_page o ORDER BY account_id DESC,championship_id DESC,competition_id DESC,season DESC,evidence_type DESC,source_id DESC,observed_at DESC LIMIT 1; END IF;
 UPDATE public.finance_migration_status SET seed_cursor=cursor_value,seeded=n<p_limit WHERE id;
 RETURN n;
END $$;
REVOKE ALL ON FUNCTION public.finance_migration_seed(integer) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.finance_migration_batch(p_limit integer DEFAULT 25,p_budget_ms integer DEFAULT 5000) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE job record;identity jsonb;predicate text;started timestamptz:=clock_timestamp();n integer:=0;src bigint;dst bigint;mismatch boolean;
BEGIN
 IF p_limit<1 OR p_limit>200 OR p_limit IS NULL OR p_budget_ms<1 OR p_budget_ms>20000 OR p_budget_ms IS NULL THEN RAISE EXCEPTION 'Invalid batch bounds'; END IF;
 IF NOT (SELECT seeded AND completed_at IS NULL FROM public.finance_migration_status WHERE id) THEN RAISE EXCEPTION 'Migration is not ready for batches'; END IF;
 -- Match cutover lock order and prevent cutover while a batch is active.
 LOCK TABLE public.rival_finance_evidence IN ACCESS SHARE MODE;
 CREATE TEMP TABLE IF NOT EXISTS finance_batch_source ON COMMIT DROP AS SELECT * FROM public.rival_finance_evidence WITH NO DATA;
 CREATE TEMP TABLE IF NOT EXISTS finance_batch_retained ON COMMIT DROP AS SELECT o.*,NULL::text AS _migration_signature FROM public.rival_finance_evidence o WITH NO DATA;
 FOR job IN SELECT entity_id FROM public.finance_migration_queue ORDER BY entity_id LIMIT p_limit FOR UPDATE SKIP LOCKED LOOP
 SELECT to_jsonb(e) INTO identity FROM public.finance_history_entities e WHERE entity_id=job.entity_id;
 IF identity IS NULL THEN CONTINUE; END IF;
 SELECT string_agg(format('%I',k)||CASE WHEN identity->>k IS NULL THEN ' IS NULL' ELSE '='||quote_literal(identity->>k) END,' AND ') INTO predicate FROM unnest(ARRAY['account_id','championship_id','competition_id','season','evidence_type','source_id']) k;
 TRUNCATE pg_temp.finance_batch_source,pg_temp.finance_batch_retained;
 EXECUTE 'INSERT INTO pg_temp.finance_batch_source SELECT * FROM public.rival_finance_evidence WHERE '||predicate;
 GET DIAGNOSTICS src=ROW_COUNT;
 INSERT INTO pg_temp.finance_batch_retained SELECT (original).*,NULL::text FROM (
 SELECT o AS original,(observed_at IS NULL OR NOT isfinite(observed_at)) AS uncertain,ROW(payload) AS fact,
 lag(ROW(payload)) OVER w AS preceding,lead(ROW(payload)) OVER w AS following
 FROM pg_temp.finance_batch_source o WINDOW w AS (ORDER BY observed_at)
 ) periods WHERE uncertain OR fact IS DISTINCT FROM preceding OR fact IS DISTINCT FROM following;
 GET DIAGNOSTICS dst=ROW_COUNT;
 UPDATE pg_temp.finance_batch_retained o SET _migration_signature=md5(jsonb_build_array(o.payload)::text);
 ANALYZE pg_temp.finance_batch_retained(_migration_signature);
 DELETE FROM public.finance_history_times WHERE entity_id=job.entity_id;
 DELETE FROM public.finance_history_states WHERE entity_id=job.entity_id;
 INSERT INTO public.finance_history_states(entity_id,signature,payload) SELECT DISTINCT job.entity_id,o._migration_signature,o.payload FROM pg_temp.finance_batch_retained o;
 INSERT INTO public.finance_history_times(entity_id,state_id,observed_at) SELECT job.entity_id,s.state_id,o.observed_at FROM pg_temp.finance_batch_retained o JOIN public.finance_history_states s ON s.entity_id=job.entity_id AND s.signature=o._migration_signature AND s.payload IS NOT DISTINCT FROM o.payload;
 -- Full retained-row equality, including IDs, nulls, payloads and timestamp precision.
 EXECUTE 'SELECT EXISTS((SELECT to_jsonb(o)-''_migration_signature'' FROM pg_temp.finance_batch_retained o EXCEPT ALL SELECT to_jsonb(v) FROM public.finance_history_preview v WHERE '||predicate||') UNION ALL (SELECT to_jsonb(v) FROM public.finance_history_preview v WHERE '||predicate||' EXCEPT ALL SELECT to_jsonb(o)-''_migration_signature'' FROM pg_temp.finance_batch_retained o))' INTO mismatch;
 IF mismatch THEN RAISE EXCEPTION 'Retained history verification failed'; END IF;
 INSERT INTO public.finance_migration_verified VALUES(job.entity_id,src,dst,clock_timestamp()) ON CONFLICT(entity_id) DO UPDATE SET source_rows=excluded.source_rows,endpoint_rows=excluded.endpoint_rows,verified_at=excluded.verified_at;
 DELETE FROM public.finance_migration_queue WHERE entity_id=job.entity_id;
 n:=n+1;
 EXIT WHEN extract(epoch FROM clock_timestamp()-started)*1000>=p_budget_ms;
 END LOOP;
 RETURN jsonb_build_object('processed',n,'pending',(SELECT count(*) FROM public.finance_migration_queue),'verified',(SELECT count(*) FROM public.finance_migration_verified));
END $$;
REVOKE ALL ON FUNCTION public.finance_migration_batch(integer,integer) FROM PUBLIC,anon,authenticated,service_role;
COMMIT;
